return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'hy','project-id-version'=>'Babilim 1.2.2','pot-creation-date'=>'2026-11-09T07:54:22+00:00','po-revision-date'=>'2026-11-09T07:54:22+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'Ուղարկվում է, երբ սեղմում եք «Միացնել Babilim-ը», և կրկին, եթե կայքը պետք է նորից գրանցվի. ձեր կայքի URL-ը, WordPress-ի, PHP-ի և Babilim-ի տարբերակները, ձեր կայքի լեզուն և դրանում օգտագործվող լեզուները, ինչպես նաև այս կայքի համար ստեղծված հանրային բանալին։','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'Ուղարկվում է ամեն ստուգման ժամանակ. տեղադրված plugin-ների և թեմաների ցանկը՝ դրանց համար տեղադրված Babilim թարգմանությունների վիճակով, օգտագործվող լեզուները և կարճ ախտորոշման կոդեր։','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'Յուրաքանչյուր հարցում ներառում է ձեր կայքի URL-ը, իսկ կայքի մուտքի թոքենը ներառվում է, երբ ծառայությունը դրա կարիքն ունի։','What Babilim sends to the service'=>'Ինչ է Babilim-ն ուղարկում ծառայությանը','Your site\'s URL'=>'Ձեր կայքի URL-ը','WordPress version'=>'WordPress-ի տարբերակ','PHP version'=>'PHP-ի տարբերակ','Babilim version'=>'Babilim-ի տարբերակ','Your site\'s language'=>'Ձեր կայքի լեզուն','Languages in use on your site'=>'Ձեր կայքում օգտագործվող լեզուներ','A public key for this site'=>'Այս կայքի հանրային բանալի','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'Այս կայքի համար ստեղծված հանրային բանալի, որն օգտագործվում է ապացուցելու, որ հարցումները իսկապես գալիս են այս կայքից։ Ուղարկվում է միայն հանրային մասը, իսկ մասնավոր մասը մնում է ձեր կայքում։','Installed plugins and themes'=>'Տեղադրված plugin-ներ և թեմաներ','For every installed plugin and theme: its name (slug), version, text domain, whether it is listed on WordPress.org, and the languages it already includes. For each Babilim translation you have installed: which version it is, when it was last checked, and whether it passed its file check.'=>'Յուրաքանչյուր տեղադրված plugin-ի և թեմայի համար՝ դրա անունը (slug), տարբերակը, text domain-ը, արդյոք այն ներկայացված է WordPress.org-ում, և այն լեզուները, որոնք արդեն ներառված են դրանում։ Ձեր տեղադրած յուրաքանչյուր Babilim թարգմանության համար՝ ինչ տարբերակ է այն, երբ է վերջին անգամ ստուգվել և արդյոք անցել է ֆայլի ստուգումը։','Source files (only if you confirm an upload)'=>'Սկզբնական ֆայլեր (միայն եթե հաստատեք վերբեռնումը)','Diagnostic codes'=>'Ախտորոշման կոդեր','Up to 20 short diagnostic codes (for example, a translation file that failed its check), each with the plugin or theme, the language and the time it happened. They never contain any text from your site or any translated text.'=>'Մինչև 20 կարճ ախտորոշման կոդ (օրինակ՝ թարգմանության ֆայլ, որը չի անցել ստուգումը), յուրաքանչյուրը plugin-ի կամ թեմայի, լեզվի և տեղի ունենալու ժամանակի հետ։ Դրանք երբեք չեն պարունակում ձեր կայքի որևէ տեքստ կամ թարգմանված տեքստ։','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Այս ցանցի %1$d կայք կարգավորված է ջնջել իր Babilim ինքնությունը, երբ հավելումը հեռացվի։ Այդ կայքին կցված վճարովի լիցենզիան այդ դեպքում չի կարող ավտոմատ վերականգնվել. պետք է կապ հաստատեք Babilim-ի աջակցության հետ՝ %2$s։ Ինքնությունը պահելու համար սեղմեք «Չեղարկել», այդ կայքի Babilim-ի կարգավորումներում հանեք «Հեռացնելիս ջնջել Babilim-ի բոլոր տվյալները» նշումը և նորից ապաակտիվացրեք։ Այնուամենայնիվ ապաակտիվացնե՞լ։' . "\0" . 'Այս ցանցի %1$d կայք կարգավորված են ջնջել իրենց Babilim ինքնությունը, երբ հավելումը հեռացվի։ Այդ կայքերին կցված վճարովի լիցենզիաներն այդ դեպքում չեն կարող ավտոմատ վերականգնվել. պետք է կապ հաստատեք Babilim-ի աջակցության հետ՝ %2$s։ Ինքնությունները պահելու համար սեղմեք «Չեղարկել», յուրաքանչյուր կայքի Babilim-ի կարգավորումներում հանեք «Հեռացնելիս ջնջել Babilim-ի բոլոր տվյալները» նշումը և նորից ապաակտիվացրեք։ Այնուամենայնիվ ապաակտիվացնե՞լ։','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s անելիք չկա։','%1$s: %2$s'=>'%1$s. %2$s','%1$s: %2$s (%3$s)'=>'%1$s. %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s՝ %2$s։ Ընտրեք լեզուն։','%d failed'=>'%d ձախողվել է' . "\0" . '%d ձախողվել է','%d not yet tried'=>'%d դեռ չի փորձվել' . "\0" . '%d դեռ չի փորձվել','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d հաշվետվություն սպասում է։ «Միշտ կիսվել» և «Չկիսվել» տարբերակները վերաբերում են բոլորին։' . "\0" . '%d հաշվետվություն սպասում է։ «Միշտ կիսվել» և «Չկիսվել» տարբերակները վերաբերում են բոլորին։','%d skipped'=>'%d բաց է թողնվել' . "\0" . '%d բաց է թողնվել','%d succeeded'=>'%d հաջողվել է' . "\0" . '%d հաջողվել է','%d to install'=>'%d տեղադրելու համար' . "\0" . '%d տեղադրելու համար','(a public key generated for this site)'=>'(այս կայքի համար ստեղծված հանրային բանալի)','(detected)'=>'(հայտնաբերված)','(generic codes and coordinates only)'=>'(միայն ընդհանուր կոդեր և կոորդինատներ)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Մաքրումը դադարեցվել է %1$s-ին՝ %2$s։ Ոչինչ չի ջնջվել։','A file in the component could not be read, so it was not packaged.'=>'Բաղադրիչի մեկ ֆայլ հնարավոր չեղավ կարդալ, ուստի այն չփաթեթավորվեց։','A host that serves only one PHP request at a time cannot complete this step.'=>'Հոսթինգը, որը միաժամանակ սպասարկում է միայն մեկ PHP հարցում, չի կարող ավարտել այս քայլը։','A part of the upload kept failing, so the upload was cancelled.'=>'Վերբեռնման մի հատվածը շարունակաբար ձախողվում էր, ուստի վերբեռնումը չեղարկվեց։','A translation cannot be requested for that locale on this site right now.'=>'Այս կայքում այդ լեզվի համար թարգմանություն այժմ հնարավոր չէ պահանջել։','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Թարգմանությունների ինդեքսի գրառումը %1$s-ին (%2$s) հակասության մեջ մտավ մեկ այլ հարցման հետ և չկիրառվեց․ պահպանվեց ամենավերջին տարբերակը։','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Թարգմանությունների ինդեքսի գրառումը %1$s-ին (%2$s) չհաջողվեց ավարտել և չկիրառվեց (%3$s)։','Account'=>'Հաշիվ','Add another language'=>'Ավելացնել ևս մեկ լեզու','Advanced'=>'Լրացուցիչ','All'=>'Բոլորը','All free-plan slots for this site are used'=>'Այս կայքի անվճար փաթեթի բոլոր տեղերը զբաղված են','All languages'=>'Բոլոր լեզուները','Already in WordPress core'=>'Արդեն առկա է WordPress-ի միջուկում','Already installed.'=>'Արդեն տեղադրված է։','Always share'=>'Միշտ կիսվել','Another installation is running; try again in a moment.'=>'Մեկ այլ տեղադրում է ընթացքի մեջ․ փորձեք մի պահ անց։','Automatic installs'=>'Ավտոմատ տեղադրումներ','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Ավտոմատ տեղադրումներն այժմ անջատված են. եթե ցանկանում եք, նորից միացրեք դրանք կարգավորումներում։','Available'=>'Հասանելի','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Հասանելի թարգմանությունները կարելի է տեղադրել մեկ սեղմումով, իսկ բացակայողները՝ պահանջել։ Երբ ավտոմատ տեղադրումները միացված են, ծառայության կողմից հասանելի նշված՝ ձեր կառավարած լեզուների թարգմանությունները տեղադրվում են օրական երկու անգամ համաժամեցման ժամանակ։','Available · %s'=>'Հասանելի է · %s','Babilim'=>'Babilim','Babilim Settings'=>'Babilim-ի կարգավորումներ','Babilim adds translations for every language checked here.'=>'Babilim-ը թարգմանություններ է ավելացնում այստեղ նշված բոլոր լեզուների համար։','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim-ը չկարողացավ հաստատել կայքից դուրս գտնվող ժամանակավոր պանակ, ուստի բաղադրիչը չփաթեթավորվեց և ոչինչ չվերբեռնվեց։ Սահմանեք BABILIM_TEMP_DIR-ը wp-config.php-ում որպես վեբ արմատային պանակից դուրս գտնվող գրելի պանակ (օրինակ՝ ձեր կայքի հանրային պանակի կողքին, ոչ թե ներսում գտնվող պանակ) կամ խնդրեք այն ձեր հոստինգ մատակարարից։','Babilim could not finish checking this site.'=>'Babilim-ը չկարողացավ ավարտել այս կայքի ստուգումը։','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim-ը չկարողացավ ավարտել միացումը (%1$s). %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim-ը չկարողացավ ավարտել այս կայքի ստուգումը (ծառայությունը չկարողացավ հետ կապվել կայքին)։ Գրանցումը դադարեցված է։','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim-ը չկարողացավ ստուգել այս կայքը, ուստի ոչինչ չի ներբեռնվի կամ տեղադրվի, մինչև ստուգումը հաջողվի։','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim-ը չկարողացավ ստուգել այս կայքը, ուստի ոչինչ չի ներբեռնվում կամ տեղադրվում։','Babilim gets translations from the Babilim service for the plugins and themes on this site that have none for your language, and installs the ones your service plan covers.'=>'Babilim-ը Babilim ծառայությունից ստանում է այս կայքի այն հավելումների և թեմաների թարգմանությունները, որոնք ձեր լեզվով թարգմանություն չունեն, և տեղադրում է այն թարգմանությունները, որոնք ընդգրկված են ձեր ծառայության փաթեթում։','Babilim has not been enabled for this site yet.'=>'Babilim-ը այս կայքի համար դեռ միացված չէ։','Babilim has not installed any translation for this language.'=>'Babilim-ը այս լեզվի համար ոչ մի թարգմանություն չի տեղադրել։','Babilim hit an error. Share an error report?'=>'Babilim-ում սխալ տեղի ունեցավ։ Կիսվե՞լ սխալի հաշվետվությամբ։','Babilim installed %d translation automatically since your last visit.'=>'Babilim-ը ձեր վերջին այցից ի վեր ավտոմատ տեղադրել է %d թարգմանություն։' . "\0" . 'Babilim-ը ձեր վերջին այցից ի վեր ավտոմատ տեղադրել է %d թարգմանություն։','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim-ն անջատված է։ Այլևս ոչինչ չի ուղարկվում. արդեն տեղադրված թարգմանությունները շարունակում են աշխատել։','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim-ը միացված է. այս կայքը հաստատված է, և գտնվել է %d բաղադրիչ։' . "\0" . 'Babilim-ը միացված է. այս կայքը հաստատված է, և գտնվել է %d բաղադրիչ։','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim-ը միացնում և ստուգում է այս կայքը… (վերջին փորձը՝ %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim-ը միացնում և ստուգում է այս կայքը… Վերաբեռնեք այս էջը կամ սպասեք ժամանակացույցով ստուգման ավարտին։','Babilim is not enabled.'=>'Babilim-ը միացված չէ։','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim-ը կարգավորված է ջնջել այս կայքի ինքնությունը, երբ հավելումը հեռացվի։ Այս կայքին կցված վճարովի լիցենզիան այդ դեպքում չի կարող ավտոմատ վերականգնվել. պետք է կապ հաստատեք Babilim-ի աջակցության հետ՝ %s։ Ինքնությունը պահելու համար սեղմեք «Չեղարկել», Babilim-ի կարգավորումներում հանեք «Հեռացնելիս ջնջել Babilim-ի բոլոր տվյալները» նշումը և նորից ապաակտիվացրեք։ Այնուամենայնիվ ապաակտիվացնե՞լ։','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim-ի ժամանակը սպառվեց այս քայլի համար, և այն կշարունակի հաջորդ ստուգման ժամանակ։','Babilim settings'=>'Babilim-ի կարգավորումներ','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim-ի համաժամացումը ծառայության կողմից ժամանակավորապես հետաձգվել է (արագության սահմանափակում). այն նորից կփորձի %s-ից հետո։','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim-ը թարմացվել է, մինչ այս վերբեռնումը սպասման մեջ էր։ Հին փաթեթը հեռացվել է. խնդրում ենք կրկին հաստատել վերբեռնումը։','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim-ը կվերբեռնի այս ֆայլերը %1$s-ից (տարբերակ %2$s). յուրաքանչյուր .php և .js ֆայլ, յուրաքանչյուր block.json ֆայլ, ինչպես նաև դրա հիմնական պանակի readme.txt, readme.md, style.css և theme.json ֆայլերը։ Դրանք օգտագործվում են թարգմանության կարիք ունեցող տեքստը գտնելու և հավելումը կամ թեման նույնականացնելու համար։','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest-ը հասանելի չէ՝ %s','Back'=>'Հետ','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Նախկինում լիցենզիա գնե՞լ եք այս դոմենի համար։ Մուտքագրեք վճարման ժամանակ ստացված վերականգնման կոդը։','Broken placeholder'=>'Կոտրված տեղապահ','Build'=>'Կառուցման նույնացուցիչ','Built'=>'Կառուցված','Bulk actions apply only to the selected language of each selected component.'=>'Զանգվածային գործողությունները կիրառվում են միայն յուրաքանչյուր ընտրված բաղադրիչի ընտրված լեզվի նկատմամբ։','Bulk actions apply to every matching language of each selected component.'=>'Զանգվածային գործողությունները կիրառվում են յուրաքանչյուր ընտրված բաղադրիչի բոլոր համընկնող լեզուների նկատմամբ։','Bulk download:'=>'Զանգվածային ներբեռնում՝','Bulk request:'=>'Զանգվածային պահանջ՝','Bulk update:'=>'Զանգվածային թարմացում՝','Bundled with the plugin'=>'Ներառված է հավելման մեջ','Bundled with the theme'=>'Ներառված է թեմայի մեջ','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Սեղմելով «Միացնել»՝ դուք համաձայնում եք վերը նշված տեղեկությունները ուղարկել Babilim-ին։','By continuing you confirm that you have the right to upload this component.'=>'Շարունակելով՝ դուք հաստատում եք, որ իրավունք ունեք վերբեռնելու այս բաղադրիչը։','Cancel'=>'Չեղարկել','Category'=>'Կատեգորիա','Check again'=>'Ստուգել նորից','Check again now'=>'Ստուգել նորից հիմա','Checkout is not available for this site right now.'=>'Վճարումը այս պահին հասանելի չէ այս կայքի համար։','Choose'=>'Ընտրել','Choose a category…'=>'Ընտրեք կատեգորիա…','Choose a language'=>'Ընտրեք լեզուն','Choose a language…'=>'Ընտրեք լեզուն…','Clear filters'=>'Մաքրել զտիչները','Close'=>'Փակել','Component'=>'Բաղադրիչ','Confirm'=>'Հաստատել','Conflicting keys'=>'Հակասող բանալիներ','Continue'=>'Շարունակել','Continue next batch (%d left)'=>'Շարունակել հաջորդ խմբաքանակը (մնացել է %d)','Continuing…'=>'Շարունակվում է…','Could not back up %s before replacing it.'=>'Չհաջողվեց պահուստավորել %s-ը փոխարինելուց առաջ։','Could not create the package archive.'=>'Չհաջողվեց ստեղծել փաթեթի արխիվը։','Could not determine active components; the existing merged index was left unchanged.'=>'Չհաջողվեց որոշել ակտիվ բաղադրիչները, առկա միավորված ինդեքսը մնաց անփոփոխ։','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Չհաջողվեց որոշել տեղադրված ընդլայնումները/թեմաները, մաքրումը բաց թողնվեց, ոչինչ չջնջվեց։','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Չհաջողվեց ծառայությունից բեռնել WordPress.org-ի լեզուների ամբողջական ցանկը, ուստի այս պահին այլ լեզու հնարավոր չէ ավելացնել։','Could not move %s into place.'=>'Չհաջողվեց տեղափոխել %s-ը իր տեղը։','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Չհաջողվեց \'%s\'-ի միավորված ինդեքսը տեղափոխել իր տեղը․ նախորդ սպասարկվող ինդեքսը (եթե կար) հեռացվել է՝ կիսով չափ թարմացված չթողնելու համար։ Այս լեզվակարգավորման համար լռելյայն դոմենի լրացում չի սպասարկվի մինչև հաջորդ հաջող վերակառուցումը։','Could not open zip: %s'=>'Չհաջողվեց բացել zip-ը՝ %s','Could not prepare %s for rollback.'=>'Չհաջողվեց պատրաստել %s ֆայլը հետգլոցման համար։','Could not read %s back after moving it into place.'=>'Չհաջողվեց կարդալ %s ֆայլը՝ այն տեղափոխելուց հետո։','Could not read: %s'=>'Չհաջողվեց կարդալ՝ %s','Could not restore the purchase: %s'=>'Չհաջողվեց վերականգնել գնումը՝ %s','Could not show a new restore code: %s'=>'Չհաջողվեց ցուցադրել նոր վերականգնման կոդ՝ %s','Could not stage %s'=>'Չհաջողվեց նախապատրաստել %s-ը','Could not stage default/%s'=>'Չհաջողվեց նախապատրաստել default/%s-ը','Could not start checkout: %s'=>'Չհաջողվեց սկսել վճարումը՝ %s','Could not verify entry count for %s'=>'Չհաջողվեց ստուգել գրառումների քանակը՝ %s','Could not write the downloaded package to disk.'=>'Չհաջողվեց ներբեռնված փաթեթը գրել սկավառակի վրա։','Could not write the staged merged index.'=>'Չհաջողվեց գրել փուլային միավորված ինդեքսը։','Current translation'=>'Ընթացիկ թարգմանություն','Custom overrides'=>'Սեփական վերասահմանումներ','Danger zone'=>'Վտանգավոր գոտի','Default supplement entry count mismatch.'=>'Լռելյայն լրացման գրառումների քանակի անհամապատասխանություն։','Delete all Babilim data on uninstall'=>'Հեռացնելիս ջնջել Babilim-ի բոլոր տվյալները','Disable Babilim'=>'Անջատել Babilim-ը','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Անջատե՞լ Babilim-ը։ Տեղադրված թարգմանությունները պահպանվում են, սակայն հետագա ստուգումներ կամ ներբեռնումներ չեն կատարվի։','Don\'t share'=>'Չկիսվել','Download'=>'Ներբեռնել','Downloaded and installed.'=>'Ներբեռնվել և տեղադրվել է։','Downloading…'=>'Ներբեռնվում է…','Downloads: %1$d/%2$d (%3$s)'=>'Ներբեռնումներ՝ %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Յուրաքանչյուր բաղադրիչի սեփական ներդրումը յուրաքանչյուր լեզվի ընդհանուր լռելյայն դոմենի լրացման մեջ։','Enable Babilim'=>'Միացնել Babilim-ը','Enabling…'=>'Միացվում է…','English (United States)'=>'Անգլերեն (Միացյալ Նահանգներ)','Entries'=>'Գրառումներ','Entry count mismatch for %s'=>'Գրառումների քանակի անհամապատասխանություն՝ %s','Error reports'=>'Սխալների հաշվետվություններ','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Այս կայքում օգտագործվող յուրաքանչյուր լեզվակարգավորում (կայքի լեզվակարգավորում, տեղադրված լեզվական փաթեթներ, օգտատերերի լեզվակարգավորումներ և ձեր ձեռքով ավելացրածները)։ Ոչ մի լեզվակարգավորում մյուսից տարբեր չի դիտարկվում։','Excluded'=>'Բացառված','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Այլ անուններով կամ ընդլայնումներով ֆայլերը ներառված չեն, ինչպես նաև uploads, cache, logs, backup, data, vendor, node_modules և languages պանակները, թաքնված ֆայլերը կամ այն ֆայլերը, որոնց անունները համապատասխանում են տարածված գաղտնի տվյալների ձևանմուշներին (wp-config*, .env*, *.sql, *.log, *.pem, *.key)։ Կոդի ֆայլերը կարող են պարունակել տեքստ կամ տվյալներ, որոնք չէիք ցանկանա կիսվել. ստուգեք դրանք, եթե վստահ չեք։ Ծառայությունը ստանալուց հետո նորից հեռացնում է նույն տեսակի ֆայլերը։','Fills in missing translations for the plugins and themes already installed on your site.'=>'Լրացնում է ձեր կայքում արդեն տեղադրված հավելումների և ձևավորման ոճերի բացակայող թարգմանությունները։','Free'=>'Անվճար','Free-plan slots'=>'Անվճար փաթեթի տեղեր','General'=>'Ընդհանուր','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Եթե սա միացված է, ապա հեռացնելիս կջնջվի նաև այս կայքի ինքնությունը։ Այս կայքին կցված վճարովի լիցենզիան հետո չի կարող ավտոմատ վերականգնվել. այն ետ ստանալու համար պետք է կապ հաստատեք Babilim-ի աջակցության հետ՝ %s։','Included'=>'Ներառված','Included in index'=>'Ներառված է ինդեքսում','Install available translations automatically'=>'Ավտոմատ տեղադրել հասանելի թարգմանությունները','Installed'=>'Տեղադրված','Installed translations are kept, but no further checks or downloads will run.'=>'Տեղադրված թարգմանությունները պահպանվում են, սակայն հետագա ստուգումներ կամ ներբեռնումներ չեն կատարվի։','Installed · %s'=>'Տեղադրված է · %s','Installed · built for %1$s, this site has %2$s'=>'Տեղադրված է · կառուցված է %1$s-ի համար, այս կայքում է %2$s','Installed · built for %s'=>'Տեղադրված է · կառուցված է %s-ի համար','Installed · built for %s, new version failed'=>'Տեղադրված է · կառուցված է %s-ի համար, նոր տարբերակը ձախողվեց','Installed · built for %s, new version scheduled'=>'Տեղադրված է · կառուցված է %s-ի համար, նոր տարբերակը պլանավորված է','Installed · built for %s, translating the new version…'=>'Տեղադրված է · կառուցված է %s-ի համար, նոր տարբերակը թարգմանվում է…','Installed · built for %s; this plugin or theme is no longer covered by the site\'s service plan'=>'Տեղադրված է · կառուցված է %s տարբերակի համար․ այս պլագինը կամ թեման այլևս ներառված չէ կայքի Ծառայության փաթեթում','Installed · built for a different version'=>'Տեղադրված է · կառուցված է այլ տարբերակի համար','Installed · built for a different version, new version failed'=>'Տեղադրված է · կառուցված է այլ տարբերակի համար, նոր տարբերակը ձախողվեց','Installed · built for a different version, new version scheduled'=>'Տեղադրված է · կառուցված է այլ տարբերակի համար, նոր տարբերակը պլանավորված է','Installed · built for a different version, translating the new version…'=>'Տեղադրված է · կառուցված է այլ տարբերակի համար, նոր տարբերակը թարգմանվում է…','Installed · built for a different version; this plugin or theme is no longer covered by the site\'s service plan'=>'Տեղադրված է · կառուցված է այլ տարբերակի համար․ այս պլագինը կամ թեման այլևս ներառված չէ կայքի Ծառայության փաթեթում','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Այն պահվում է ծառայության հոստինգ մատակարարի մոտ և մշակվում է արհեստական բանականության մոդելներով՝ թարգմանությունը ստեղծելու համար։','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Պահել իմ սեփական թարգմանության վերասահմանումները՝ ամեն ինչ մաքրելիս կամ այս հավելումը ապատեղադրելիս։','Language'=>'Լեզու','Language:'=>'Լեզու՝','Languages'=>'Լեզուներ','Languages found on this site: %s.'=>'Այս կայքում գտնված լեզուներ՝ %s։','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Վերջին մաքրումը %1$s-ին․ %2$d նոր նշված, %3$d ֆայլ ջնջված, %4$d գրառում հեռացված։','Maintenance'=>'Սպասարկում','Maintenance status is not available right now.'=>'Սպասարկման կարգավիճակը այս պահին հասանելի չէ։','Manifest unavailable: %s'=>'Մանիֆեստը հասանելի չէ՝ %s','Negation reversed'=>'Ժխտումը շրջված է','No'=>'Ոչ','No build is available to download for this locale.'=>'Այս տեղայնացման համար ներբեռնելու հավաքակ չկա։','No cleanup has run yet.'=>'Մաքրում դեռ չի կատարվել։','No components match these filters. %s'=>'Ոչ մի բաղադրիչ չի համապատասխանում այս զտիչներին։ %s','No components synced yet.'=>'Բաղադրիչներ դեռ չեն համաժամեցվել։','No installed translation matches.'=>'Տեղադրված թարգմանություններից ոչ մեկը չի համապատասխանում։','No language is managed yet.'=>'Դեռ ոչ մի լեզու չի կառավարվում։','No pending challenge for this nonce.'=>'Այս nonce-ի համար սպասվող challenge չկա։','No pending challenge to verify.'=>'Ստուգման ենթակա սպասվող մարտահրավեր չկա։','No plugins or themes found.'=>'Հավելումներ կամ ձևավորման ոճեր չեն գտնվել։','No previous build to roll back to.'=>'Չկա նախորդ կառուցում, որին հնարավոր լինի վերադառնալ։','No record for %s'=>'%s-ի համար գրառում չկա','No site id is on file to rotate a token for.'=>'Թոկենը թարմացնելու համար կայքի ID չի գտնվել։','No — component inactive'=>'Ոչ՝ բաղադրիչը ապաակտիվ է','No — component removed'=>'Ոչ՝ բաղադրիչը հեռացված է','No — installed version differs from the active one'=>'Ոչ — տեղադրված տարբերակը տարբերվում է ակտիվից','Not a valid server_build_id: %s'=>'Վավեր server_build_id չէ՝ %s','Not covered by the free service plan'=>'Չի ներառվում անվճար սպասարկման փաթեթում','Not installed'=>'Տեղադրված չէ','Not registered yet'=>'Դեռ գրանցված չէ','Not supported'=>'Չի աջակցվում','Not verified'=>'Չստուգված','Note (optional)'=>'Նշում (ըստ ցանկության)','Nothing to choose.'=>'Ընտրելու ոչինչ չկա։','Nothing to confirm.'=>'Հաստատելու ոչինչ չկա։','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Լռելյայն անջատված է. հավելումը ջնջելիս այս կայքի նույնականացման տվյալները պահպանվում են, որպեսզի վերատեղադրման դեպքում հնարավոր լինի դրանք կրկին օգտագործել։','One or more served files no longer match the manifest.'=>'Մեկ կամ մի քանի տրամադրվող ֆայլեր այլևս չեն համապատասխանում մանիֆեստին։','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Միանվագ գնում այս կայքի համար՝ %1$s %2$s։ Ներառում է թարգմանությունների բոլոր հետագա թարմացումները։ Վճարումը կատարվում է Paddle-ի միջոցով նոր ներդիրում։','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Սա կարող է անել միայն ցանցի ադմինիստրատորը, քանի որ այն փոխում է այս ցանցի բոլոր կայքերի կողմից օգտագործվող ընդհանուր թարգմանության ֆայլերը։','Only plugins and themes can be packaged.'=>'Կարելի է փաթեթավորել միայն հավելումներ և ձևավորման ոճեր։','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Միայն երբ հաստատում եք WordPress.org-ում չգտնվող հավելումի կամ թեմայի վերբեռնումը. յուրաքանչյուր .php և .js ֆայլ, յուրաքանչյուր block.json ֆայլ, ինչպես նաև տվյալ բաղադրիչի հիմնական պանակի readme.txt, readme.md, style.css և theme.json ֆայլերը՝ zip ձևաչափով, այն բանից հետո, երբ տարածված գաղտնի տվյալներին համապատասխանող ֆայլերը բացառվում են։','Open Babilim settings'=>'Բացել Babilim-ի կարգավորումները','Original language'=>'Բնօրինակ լեզու','Original string'=>'Բնօրինակ տող','Paid'=>'Վճարովի','Partner'=>'Գործընկեր','Please check that your site can be reached from the internet, then try again.'=>'Խնդրում ենք ստուգել, որ ձեր կայքը հասանելի է համացանցից, և նորից փորձել։','Please choose a category for this report.'=>'Խնդրում ենք ընտրել այս հաշվետվության կատեգորիան։','Plugin'=>'Հավելում','Plugin · %s'=>'Հավելում · %s','Plugins'=>'Հավելումներ','Preview'=>'Նախադիտում','Purchase restored. This site is now licensed.'=>'Գնումը վերականգնվեց։ Այս կայքն այժմ լիցենզավորված է։','Re-parsed entry count did not match the built index.'=>'Կրկին վերլուծված գրառումների քանակը չհամընկավ կառուցված ինդեքսի հետ։','Re-verify'=>'Նորից ստուգել','Rebuild index now'=>'Վերակառուցել ինդեքսը հիմա','Refusing to write outside the Babilim language-file directory.'=>'Հրաժարվում եմ գրել Babilim-ի լեզվական ֆայլերի գրացուցակից դուրս։','Registration response was missing required fields.'=>'Գրանցման պատասխանում բացակայում էին պարտադիր դաշտեր։','Registration restarted.'=>'Գրանցումը վերսկսվեց։','Remove'=>'Հեռացնել','Remove everything Babilim installed'=>'Հեռացնել ամեն ինչ, ինչ տեղադրել է Babilim-ը','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Հեռացնե՞լ այն ամենը, ինչ տեղադրել է Babilim-ը։ Սա կջնջի այս կայքի բոլոր հավելումների և թեմաների համար Babilim-ի տեղադրած բոլոր լեզվական ֆայլերը։','Remove the %2$s translation of %1$s from this site?'=>'Հեռացնե՞լ %1$s բաղադրիչի %2$s թարգմանությունն այս կայքից։','Removed %d installed component.'=>'Հեռացվեց %d տեղադրված բաղադրիչ։' . "\0" . 'Հեռացվեց %d տեղադրված բաղադրիչ։','Removed after a failed integrity check'=>'Հեռացվել է ամբողջականության ստուգումը չանցնելուց հետո','Removed.'=>'Հեռացվել է։','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Հեռացնում է Babilim-ի տեղադրած յուրաքանչյուր լեզվի ֆայլը այս կայքի բոլոր հավելումների և թեմաների համար։','Report a problem'=>'Հաղորդել խնդրի մասին','Report translation'=>'Հաղորդել թարգմանության մասին','Request newer translation'=>'Պահանջել ավելի նոր թարգմանություն','Request translation'=>'Պահանջել թարգմանություն','Requestable'=>'Հնարավոր է պահանջել','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Թարգմանություն պահանջելիս այս հավելումը կամ ձևավորման ոճը զբաղեցնում է այս կայքի համար անվճար սպասարկման փաթեթի տեղերից մեկը (սահմանաչափը ձևավորման ոճերի համար %1$d է, իսկ հավելումների համար՝ %2$d), եթե արդեն չունի այդպիսին։ Տեղը մնում է օգտագործված, և ձախողված թարգմանությունը այն չի ազատում։','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Թարգմանություն պահանջելիս այս հավելումը կամ ձևավորման ոճը զբաղեցնում է այս կայքի համար անվճար սպասարկման փաթեթի տեղերից մեկը, եթե արդեն չունի այդպիսին։ Տեղը մնում է օգտագործված, և ձախողված թարգմանությունը այն չի ազատում։','Requesting…'=>'Հարցումն ուղարկվում է…','Restart registration'=>'Վերսկսել գրանցումը','Restore code'=>'Վերականգնման կոդ','Restore purchase'=>'Վերականգնել գնումը','Retry request'=>'Կրկնել հարցումը','Roll back'=>'Հետ գլորել','Roll back and report'=>'Հետ գլորել և հաղորդել','Roll back and send report'=>'Հետ վերադարձնել և ուղարկել հաշվետվություն','Roll back the %2$s translation of %1$s to the previous build?'=>'Հետ վերադարձնե՞լ %1$s-ի %2$s թարգմանությունը նախորդ կառուցմանը։','Rolled back and reported.'=>'Վերադարձվել և հաղորդվել է։','Rolled back to the previous build.'=>'Վերադարձվեց նախորդ հավաքակին։','Rolled back, but the report could not be sent: %s'=>'Վերադարձվել է, բայց հաշվետվությունը չհաջողվեց ուղարկել՝ %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Հետգլոցումը կվերագրի «%1$s» (%2$s) ֆայլը, որն այժմ տրամադրվում է մեկ այլ տեղադրված բաղադրիչի համար (%3$s)․ ոչինչ չի փոփոխվել։','Rotate-token response was missing site_token.'=>'Թոքենի թարմացման պատասխանում site_token-ը բացակայում էր։','Save changes'=>'Պահպանել փոփոխությունները','Scheduled, waiting to be processed'=>'Պլանավորված է, սպասում է մշակման','Search'=>'Որոնել','Search components'=>'Որոնել բաղադրիչներ','Search the installed translations'=>'Որոնել տեղադրված թարգմանություններում','Select all'=>'Ընտրել բոլորը','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Ընտրեք ավելի քիչ բաղադրիչներ՝ առավելագույնը %1$d գործողություն մեկ գործարկման ժամանակ (դուք ընտրել եք %2$d)։','Send report'=>'Ուղարկել հաշվետվություն','Service plan'=>'Սպասարկման փաթեթ','Settings'=>'Կարգավորումներ','Share error reports'=>'Կիսվել սխալների հաշվետվություններով','Share this report'=>'Կիսվել այս հաշվետվությամբ','Show a new restore code'=>'Ցուցադրել նոր վերականգնման կոդ','Show the "Report translation" entry in the admin toolbar'=>'Ցուցադրել «Զեկուցել թարգմանության մասին» կետը ադմինի գործիքագոտում','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Այս բաղադրիչի տեքստի մի մասը կոշտ կոդավորված է նրա հեղինակի կողմից և չի կարող թարգմանվել լեզվական փաթեթով։','Status'=>'Կարգավիճակ','Status unknown'=>'Կարգավիճակն անհայտ է','String context'=>'Տողի համատեքստ','Suggested translation'=>'Առաջարկվող թարգմանություն','Supplementary translation index'=>'Լրացուցիչ թարգմանությունների ինդեքս','Supplementary translation index rebuilt.'=>'Լրացուցիչ թարգմանությունների ինդեքսը վերակառուցվեց։','Supplementary translation maintenance'=>'Լրացուցիչ թարգմանությունների սպասարկում','Supplementary translations'=>'Լրացուցիչ թարգմանություններ','Sweep aborted without orphaning anything: %s.'=>'Մաքրումը ընդհատվեց առանց որևէ բան որբ թողնելու՝ %s։','Sweep complete: %d file deleted.'=>'Մաքրումը ավարտված է. ջնջվել է %d ֆայլ։' . "\0" . 'Մաքրումը ավարտված է. ջնջվել է %d ֆայլ։','Sweep now'=>'Մաքրել հիմա','Sync complete.'=>'Համաժամեցումն ավարտված է։','Thank you. Your report was sent.'=>'Շնորհակալություն։ Ձեր հաշվետվությունն ուղարկվել է։','That component is not installed on this site, so a translation cannot be requested for it.'=>'Այդ բաղադրիչը տեղադրված չէ այս կայքում, ուստի դրա համար թարգմանություն հնարավոր չէ պահանջել։','That does not look like a restore code.'=>'Սա վերականգնման կոդի նման չէ։','That is not a valid WordPress locale code. Nothing was saved.'=>'Սա վավեր WordPress-ի տեղայնացման կոդ չէ։ Ոչինչ չպահվեց։','That is not a valid build identifier.'=>'Սա վավեր կառուցման նույնացուցիչ չէ։','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Այդ վերբեռնման էկրանը հնացած էր. դրանից հետո պատրաստվել է մեկ այլ վերբեռնում։ Ոչինչ չի ուղարկվել։ Դիտեք ընթացիկը Թարգմանությունների ցանկից։','The change could not be recorded in the translation index; please try again.'=>'Փոփոխությունը հնարավոր չեղավ գրանցել թարգմանությունների ինդեքսում։ Խնդրում ենք կրկին փորձել։','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Մաքրումը կատարվեց, բայց դրա որոշ փոփոխություններ չհաջողվեց գրանցել թարգմանությունների ինդեքսում․ հաջորդ մաքրումը կրկին կփորձի դրանք։','The component has no files that can be uploaded.'=>'Բաղադրիչը չունի վերբեռնվող ֆայլեր։','The component is not inside the plugins or themes directory.'=>'Բաղադրիչը չի գտնվում plugins կամ themes գրացուցակում։','The component\'s main file was not found.'=>'Բաղադրիչի հիմնական ֆայլը չգտնվեց։','The download response was missing a usable location.'=>'Ներբեռնման պատասխանում օգտագործելի հասցե բացակայում էր։','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Այս կետը բացում է վահանակ, որտեղ կարելի է որոնել Babilim-ի այս կայքում տեղադրած թարգմանությունները և դրանցից որևէ մեկի մասին զեկուցել։','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'«%1$s» դաշտը չափազանց երկար է. այն ունի %2$d նիշ, իսկ սահմանաչափը %3$d է։ Ոչինչ չի ուղարկվել. խնդրում ենք կրճատել և նորից փորձել։','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Անվճար սպասարկման փաթեթը յուրաքանչյուր կայքին տրամադրում է հավելումների և ձևավորման ոճերի սահմանափակ քանակությամբ տեղեր։ Օգտագործվող տեղերը ցուցադրվում են Կարգավորումներում՝ Babilim-ը միացնելուց հետո։','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Տրված \'%1$s\' դոմենը չի համապատասխանում ո՛չ փաթեթի մանիֆեստի սեփական \'%2$s\' slug-ին, ո՛չ էլ նրա text_domain-ին՝ \'%3$s\'։','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'«%s»-ի միավորված ինդեքսը վերակառուցվեց, բայց թարգմանությունների ինդեքսը չկարողացավ այն գրանցել․ հաջորդ վերակառուցումը կրկին կփորձի։','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Բնօրինակ տեքստը և դրանից ստեղծված թարգմանությունները կտրամադրվեն այլ կայքերին, որոնք տեղադրում են նույն տարբերակը։','The package declares no main translation file.'=>'Փաթեթը հիմնական թարգմանության ֆայլ չի նշում։','The package has no %s for its own text domain.'=>'Փաթեթը չունի %s իր սեփական տեքստային դոմենի համար։','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Փաթեթի մանիֆեստի \'%1$s\' տեսակը չի համապատասխանում պահանջված \'%2$s\' տեսակին։','The package produced no servable main translation file.'=>'Փաթեթը չի ստեղծել տրամադրման ենթակա հիմնական թարգմանության ֆայլ։','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Փաթեթի տեքստային դոմենը \'%1$s\' չի համապատասխանում այս կայքի բաղադրիչի օրինակին (\'%2$s\'), ուստի այն չի տեղադրվել։','The packaged component could not be read.'=>'Փաթեթավորված բաղադրիչը հնարավոր չեղավ կարդալ։','The registration challenge is not in the expected form.'=>'Գրանցման մարտահրավերը ակնկալվող ձևաչափով չէ։','The report could not be sent.'=>'Հաշվետվությունը չհաջողվեց ուղարկել։','The search could not be completed.'=>'Որոնումը չհաջողվեց ավարտել։','The service asked this site to wait before syncing again.'=>'Ծառայությունը խնդրել է այս կայքին սպասել՝ նախքան նորից համաժամեցնելը։','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Ծառայությունը չկարողացավ կապ հաստատել ձեր կայքի հետ։ Հավանաբար firewall-ը, անվտանգության հավելումը կամ հոսթինգի կանոնը արգելափակում է հարցումը. խնդրում ենք թույլատրել հարցումները դեպի /wp-json/babilim/v1/challenge։','The service\'s upload offer was incomplete.'=>'Ծառայության վերբեռնման առաջարկը թերի էր։','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Տեքստային դոմենը՝ «%1$s» (%2$s), արդեն տրամադրվում է մեկ այլ տեղադրված բաղադրիչի համար (%3$s)․ ոչինչ չի տեղադրվել։','The upload is kept until you ask Babilim to delete it.'=>'Վերբեռնումը պահվում է, մինչև դուք Babilim-ից չխնդրեք ջնջել այն։','Theme'=>'Ոճ','Theme · %s'=>'Ձևավորման ոճ · %s','Themes'=>'Ձևավորման ոճեր','There is no upload in progress.'=>'Ընթացքի մեջ գտնվող վերբեռնում չկա։','There is no upload waiting for confirmation.'=>'Հաստատման սպասող վերբեռնում չկա։','These are the languages this site uses. You can change them in %s.'=>'Սրանք այն լեզուներն են, որոնք այս կայքն օգտագործում է։ Դուք կարող եք դրանք փոխել %s։','These fields will be sent:'=>'Այս դաշտերը կուղարկվեն․','This build is not one this site currently knows about for this component/locale.'=>'Այս հավաքակը չի մտնում այն հավաքակների թվում, որոնք այս կայքը ներկայումս ճանաչում է այս բաղադրիչի/տեղայնացման համար։','This component does not declare a version number, so a translation cannot be requested for it.'=>'Այս բաղադրիչը չի նշում տարբերակի համար, ուստի դրա համար թարգմանություն հնարավոր չէ պահանջել։','This component is larger than the service accepts, so it cannot be uploaded.'=>'Այս բաղադրիչը մեծ է, քան ծառայությունն ընդունում է, ուստի այն հնարավոր չէ վերբեռնել։','This component was already uploaded. Babilim is checking it now.'=>'Այս բաղադրիչն արդեն վերբեռնված է։ Babilim-ն այժմ ստուգում է այն։','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Այս բաղադրիչի տարբերակի համարը %d նիշից երկար է, ինչը Babilim-ը չի կարող մշակել, ուստի դրա համար թարգմանություն հնարավոր չէ պահանջել։','This issues a new restore code and the previous one stops working. Continue?'=>'Սա տրամադրում է նոր վերականգնման կոդ, և նախորդը կդադարի աշխատել։ Շարունակե՞լ։','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Այս ցանցն ունի չափազանց շատ կայքեր՝ դրանք մեկ առ մեկ ստուգելու համար, և դրանցից մի քանիսը կարող են կարգավորված լինել ջնջել իրենց Babilim ինքնությունը, երբ հավելումը հեռացվի։ Նման կայքին կցված վճարովի լիցենզիան այդ դեպքում չի կարող ավտոմատ վերականգնվել. պետք է կապ հաստատեք Babilim-ի աջակցության հետ՝ %s։ Ինքնությունները պահելու համար սեղմեք «Չեղարկել», յուրաքանչյուր կայքի Babilim-ի կարգավորումներում հանեք «Հեռացնելիս ջնջել Babilim-ի բոլոր տվյալները» նշումը և նորից ապաակտիվացրեք։ Այնուամենայնիվ ապաակտիվացնե՞լ։','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Այս ընդլայնման սեփական տարբերակը, որպեսզի ծառայությունը կարողանա ձեզ ասել թարմացնել այն, եթե այն չափազանց հին է կապ հաստատելու համար։','This report does not name a valid plugin or theme and locale.'=>'Այս հաշվետվությունում նշված չէ վավեր հավելման կամ թեմայի Անուն և լեզու։','This report does not name an installed string.'=>'Այս հաշվետվության մեջ տեղադրված տողի Անուն չի նշված։','This report is missing a valid build to report against.'=>'Այս հաշվետվությունում բացակայում է վավեր հավաքակ, որի մասին պետք է հաղորդել։','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Այս հաշվետվությունը կհրապարակվի հանրությանը GitHub-ում և կարող է պահպանվել երրորդ կողմերի կողմից։','This restore code was not recognised for this site.'=>'Այս վերականգնման կոդը չճանաչվեց այս կայքի համար։','This site already has an active registration that can no longer be recovered automatically.'=>'Այս կայքն արդեն ունի ակտիվ գրանցում, որը այլևս հնարավոր չէ ավտոմատ վերականգնել։','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Այս կայքն ունի %1$d բաղադրիչ %2$d լեզվով, ինչը պահանջում է ստուգման %3$d փաթեթ․ Babilim-ը մեկ գործարկման ընթացքում կարող է մշակել առավելագույնը %4$d։ Նվազեցրեք կառավարվող լեզուների քանակը Կարգավորումներում կամ ապաակտիվացրեք չօգտագործվող հավելումները և ոճերը, ապա սեղմեք «Ստուգել նորից»։','This site has no purchase to show a code for.'=>'Այս կայքը չունի գնում, որի համար հնարավոր լինի կոդ ցուցադրել։','This site is already licensed. Reload the page.'=>'Այս կայքն արդեն լիցենզավորված է։ Թարմացրեք էջը։','This site is not registered with Babilim yet.'=>'Այս կայքը դեռ գրանցված չէ Babilim-ում։','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Այս կայքը գերազանցում է ծառայության՝ մեկ համաժամեցման ընթացքում ընդունվող չափը, ուստի որոշ տարրեր բաց են թողնվել՝ %1$d բաղադրիչ և %2$d լեզու։','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Այս կայքը բազմակայք ցանցի մաս է, որը նոր թարգմանություններ ավտոմատ չի տեղադրում։ Արդեն տեղադրված թարգմանությունները շարունակում են թարմացվել։','This site is verified.'=>'Այս կայքը ստուգված է։','This site must be verified first.'=>'Այս կայքը նախ պետք է ստուգվի։','This site\'s URL, so the service can verify you own it.'=>'Այս կայքի URL-ը, որպեսզի ծառայությունը կարողանա ստուգել, որ դուք եք դրա սեփականատերը։','This site\'s address is too long for Babilim to register.'=>'Այս կայքի հասցեն չափազանց երկար է Babilim-ում գրանցելու համար։','This site\'s configured locale.'=>'Այս կայքի կարգավորված լեզվակարգը։','This site\'s locale code is not one Babilim can register.'=>'Այս կայքի տեղայնացման կոդը չի կարող գրանցվել Babilim-ում։','This string can\'t be reported from this site.'=>'Այս տողը հնարավոր չէ հաղորդել այս կայքից։','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Այս տողը այս կայքում տեղադրված թարգմանությունների մեջ չէ։ Կրկին որոնեք և ընտրեք այն ցանկից։','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Այս թարգմանությունը թարմացվել է ձեր որոնումից հետո։ Կրկին որոնեք և ընտրեք տողը նոր ցանկից։','To translate this component, Babilim needs its source.'=>'Այս բաղադրիչը թարգմանելու համար Babilim-ին անհրաժեշտ է դրա աղբյուրը։','Too many attempts. Try again tomorrow.'=>'Չափազանց շատ փորձեր։ Կրկին փորձեք վաղը։','Too many reports today. Try again tomorrow.'=>'Այսօր չափազանց շատ հաշվետվություններ են։ Փորձեք վաղը։','Too many requests.'=>'Չափազանց շատ հարցումներ։','Toolbar'=>'Գործիքագոտի','Translating…'=>'Թարգմանվում է…','Translation does not load'=>'Թարգմանությունը չի բեռնվում','Translation failed'=>'Թարգմանությունը ձախողվեց','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'%s թղթապանակում տեղադրած թարգմանության ֆայլերը միշտ գերակայում են Babilim-ի ֆայլերից։ Դրանք պահվում են, քանի դեռ չեք հանել այս նշումը։','Translation requested.'=>'Թարգմանությունը պահանջվել է։','Translations'=>'Թարգմանություններ','Type'=>'Տեսակ','Type at least 2 characters to search.'=>'Որոնելու համար մուտքագրեք առնվազն 2 նիշ։','Unexpected HTTP %d response.'=>'Չսպասված HTTP %d պատասխան։','Uninstall'=>'Ապատեղադրում','Unknown kind: %s'=>'Անհայտ տեսակ՝ %s','Unsafe domain: %s'=>'Անապահով դոմեն՝ %s','Unsafe locale: %s'=>'Անապահով լեզվակարգ՝ %s','Unsafe slug: %s'=>'Անապահով slug՝ %s','Unsafe text_domain: %s'=>'Անապահով text_domain՝ %s','Update'=>'Թարմացնել','Update available'=>'Թարմացում հասանելի է','Updates'=>'Թարմացումներ','Updating…'=>'Թարմացվում է…','Upgrade this site'=>'Բարելավել այս կայքը','Upload and request'=>'Վերբեռնել և հայցել','Upload cancelled.'=>'Վերբեռնումը չեղարկվել է։','Upload complete — translation requested.'=>'Վերբեռնումն ավարտվեց — թարգմանությունը պահանջվել է։','Upload expired before it finished'=>'Վերբեռնման ժամկետն անցել է ավարտից առաջ','Upload in progress — continue or cancel'=>'Վերբեռնումը ընթացքի մեջ է — շարունակեք կամ չեղարկեք','Upload this component?'=>'Վերբեռնե՞լ այս բաղադրիչը','Upload was not accepted'=>'Վերբեռնումը չընդունվեց','Uploading'=>'Վերբեռնվում է','Uploading part %1$d of %2$d…'=>'Վերբեռնվում է մասը %1$d %2$d-ից…','Uploading…'=>'Վերբեռնվում է…','Verified'=>'Ստուգված է','Verify response was missing site_token.'=>'Ստուգման պատասխանում site_token-ը բացակայում էր։','Version %s'=>'Տարբերակ %s','What is sent when you enable Babilim'=>'Ինչ է ուղարկվում Babilim-ը միացնելիս','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Երբ Babilim-ի ներսում ինչ-որ բան ձախողվի, ուղարկեք սխալի հաշվետվություն Babilim ծառայությանը, որպեսզի այն հրապարակվի որպես հանրային issue GitHub-ում։ Հաշվետվությունն ուղարկվում է որպես այս կայքից՝ նույն նույնականացմամբ, ինչ Babilim ծառայության մյուս բոլոր հարցումները։ Ծառայությունը հրապարակում է միայն սխալի կոդը և տարբերակները որպես հանրային issue GitHub-ում. հանրային issue-ն չի պարունակում կայքի հասցե, բովանդակություն կամ ֆայլերի ուղիներ։ Լռելյայն անջատված է։','Where you saw this (optional)'=>'Որտեղ եք դա տեսել (ըստ ցանկության)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Երբ սա միացված է, ծառայության կողմից հասանելի նշված՝ ձեր կառավարած լեզուների թարգմանությունները տեղադրվում են օրական երկու անգամ համաժամեցման ժամանակ։','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Սխալ է այս համատեքստի համար','Wrong meaning'=>'Սխալ նշանակություն','Wrong plural form'=>'Սխալ հոգնակի ձև','Wrong term'=>'Սխալ տերմին','Yes'=>'Այո','You are not allowed to do this.'=>'Դուք իրավունք չունեք կատարել այս գործողությունը։','Your PHP version, for compatibility.'=>'Ձեր PHP-ի տարբերակը՝ համատեղելիության համար։','Your WordPress version, to serve compatible translation files.'=>'Ձեր WordPress-ի տարբերակը՝ համատեղելի թարգմանության ֆայլեր տրամադրելու համար։','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ձեր նոր վերականգնման կոդը՝ %s։ Պահեք այն անվտանգ տեղում. նախորդ կոդն այլևս չի աշխատում։','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Ձեր հաշվետվությունը մշակվում է ավտոմատ կերպով AI մոդելների կողմից և կարող է բարելավել այս թարգմանությունը այլ կայքերի համար։','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ձեր կայքը պատասխանեց, բայց ոչ սպասվածով։ REST API-ի հասցեները կարող են վերաձևակերպվել (rewrite) մեկ այլ հավելումի կողմից, կամ այդ վերջնակետը կարող է քեշավորված լինել. խնդրում ենք /wp-json/babilim/v1/challenge-ը հանել քեշավորումից և հասցեների վերաձևակերպումից։','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ձեր կայքը չափազանց երկար ժամանակ պահանջեց պատասխանելու համար։ Խնդրում ենք փորձել ավելի ուշ և ստուգել, որ ձեր հոսթինգը չափազանց դանդաղ կամ ծանրաբեռնված չէ։','Zip has no manifest.json.'=>'Zip-ում manifest.json չկա։','Zip is missing expected default file: %s'=>'Zip-ում բացակայում է սպասվող լռելյայն ֆայլը՝ %s','Zip is missing expected file: %s'=>'Zip-ում բացակայում է սպասվող ֆայլը՝ %s','_manifest.json has an unexpected structure'=>'_manifest.json-ն ունի անսպասելի կառուցվածք','could not read _manifest.json: %s'=>'չհաջողվեց կարդալ _manifest.json-ը՝ %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest-ը բացակայում է կամ ունի անվավեր «%s»։','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest-ի «server_build_id»-ն վավեր build id չէ։','failed to parse _manifest.json: %s'=>'չհաջողվեց վերլուծել _manifest.json-ը՝ %s','it would orphan %1$d of %2$d managed components (more than half)'=>'այն որբ կդարձնի %2$d կառավարվող բաղադրիչներից %1$d-ը (կեսից ավելին)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'այն որբ կդարձնի յուրաքանչյուր կառավարվող %1$s բաղադրիչ (%2$d-ից %2$d)','l10n.php entry count mismatch for %s'=>'l10n.php-ի գրառումների քանակի անհամապատասխանություն %s ֆայլի համար','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json-ն ունի անվավեր «default_domain_entries»։','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json-ն ունի անվավեր «default_domain_files»։','manifest.json in the zip is not valid JSON.'=>'Zip-ի manifest.json-ը վավեր JSON չէ։','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json-ում \'%s\'-ը բացակայում է կամ անվավեր է։','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json-ում \'build_no\'-ը բացակայում է կամ անվավեր է։','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json-ում \'entries\'-ը բացակայում է կամ անվավեր է։','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json-ում \'extra_domains\'-ը բացակայում է կամ անվավեր է։','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json-ում \'files\'-ը բացակայում է կամ անվավեր է։','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json-ի \'%s\' դաշտը չի համապատասխանում ակնկալվող արժեքին։','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json-ի «contract»-ը վավեր տարբերակի տող չէ։','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json-ի «kind»-ը պետք է լինի «plugin» կամ «theme»։','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json-ի «server_build_id»-ն վավեր build id չէ։','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json-ի «status» դաշտի Կարգավիճակ պետք է լինի «published»։','nonce must be a hexadecimal string.'=>'nonce-ը պետք է լինի տասնվեցական տող։','per day'=>'օրական','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256-ի անհամապատասխանություն %s ֆայլի համար','sha256 mismatch for default/%s'=>'sha256-ի անհամապատասխանություն default/%s ֆայլի համար','component kind in the sweep brake messageplugin'=>'հավելում','component kind in the sweep brake messagetheme'=>'թեմա','problem report categoryOther'=>'Այլ','translation statusAvailable'=>'Հասանելի է','translation statusInstalled'=>'Տեղադրված է','Babilim translation turned off.'=>'Babilim թարգմանությունն անջատված է։','Stop using Babilim translation'=>'Դադարեցնել Babilim թարգմանության օգտագործումը','Use Babilim translation'=>'Օգտագործել Babilim թարգմանությունը','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the theme\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Դադարեցնե՞լ %1$s (%2$s) թեմայի Babilim թարգմանության օգտագործումը։ WordPress-ը փոխարենը կօգտագործի թեմայի սեփական կամ WordPress.org թարգմանությունը։ Կարող եք ցանկացած պահի վերադառնալ։','Stop using the Babilim translation of %1$s (%2$s)? WordPress will use the plugin\'s own or WordPress.org translation instead. You can switch back at any time.'=>'Դադարեցնե՞լ %1$s (%2$s) պլագինի Babilim թարգմանության օգտագործումը։ WordPress-ը փոխարենը կօգտագործի պլագինի սեփական կամ WordPress.org թարգմանությունը։ Կարող եք ցանկացած պահի վերադառնալ։']];